function creativeLine() {

	let lineNum = random(height / 40, height / 20);

	noFill();

	for (let i = 1; i < lineNum * 2; i += random()) {
		let offset = random(-width, width);
		strokeCap(SQUARE);
		strokeWeight(random(5, 40));
		push();
		rotate(angleLine);
		gradientLine(
			(i / lineNum) * random(width) + offset,
			(height / lineNum) * i,
			width - (i / lineNum) * random(width) - offset,
			(height / lineNum) * i,
			random(colorset),
			random(colorset)
		);
		rotate(PI / 2);
		gradientLine(
			(i / lineNum) * random(width) + offset,
			(height / lineNum) * i,
			width - (i / lineNum) * random(width) - offset,
			(height / lineNum) * i,
			random(colorset),
			random(colorset)
		);
		pop();
	}
}

function gradientLine(x1, y1, x2, y2, color1, color2) {
	// linear gradient from start to end of line
	// color from color1 to color2
	var grad = this.drawingContext.createLinearGradient(x1, y1, x2, y2);
	grad.addColorStop(0, color1);
	grad.addColorStop(1, color2);

